import pandas as pd

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"]

    # Get the high_ts watermark value
    high_ts = watermark["high_ts"].iloc[0]

    # Filter CDC events to only those at or before watermark
    cdc_filtered = cdc_events[cdc_events["event_ts"] <= high_ts].copy()

    # Sort events by item_id, event_ts, event_seq for deterministic processing
    cdc_sorted = cdc_filtered.sort_values(
        by=["item_id", "event_ts", "event_seq"],
        ascending=[True, True, True]
    ).reset_index(drop=True)

    # Create a dictionary from target_snapshot for easier updates
    snapshot_dict = {}
    for _, row in target_snapshot.iterrows():
        snapshot_dict[row["item_id"]] = {
            "qty_on_hand": row["qty_on_hand"],
            "last_event_ts": row["last_event_ts"]
        }

    # Process each CDC event in order
    for _, event in cdc_sorted.iterrows():
        item_id = event["item_id"]
        op = event["op"]
        qty = event["qty"]
        event_ts = event["event_ts"]

        if op == "R":  # Receipt - add to quantity
            if item_id not in snapshot_dict:
                # Item doesn't exist, start from 0
                snapshot_dict[item_id] = {
                    "qty_on_hand": qty,
                    "last_event_ts": event_ts
                }
            else:
                # Item exists, add to it
                snapshot_dict[item_id]["qty_on_hand"] += qty
                snapshot_dict[item_id]["last_event_ts"] = event_ts

        elif op == "A":  # Adjustment - set absolute value
            # Adjustment always sets absolute value (creates if doesn't exist)
            snapshot_dict[item_id] = {
                "qty_on_hand": qty,
                "last_event_ts": event_ts
            }

        elif op == "D":  # Delete - remove item
            if item_id in snapshot_dict:
                del snapshot_dict[item_id]

    # Convert back to DataFrame
    result_rows = []
    for item_id, data in sorted(snapshot_dict.items()):
        result_rows.append({
            "item_id": item_id,
            "qty_on_hand": data["qty_on_hand"],
            "last_event_ts": data["last_event_ts"]
        })

    if result_rows:
        new_snapshot = pd.DataFrame(result_rows)
    else:
        new_snapshot = pd.DataFrame(columns=["item_id", "qty_on_hand", "last_event_ts"])

    # Ensure correct dtypes
    new_snapshot["item_id"] = new_snapshot["item_id"].astype("int64")
    new_snapshot["qty_on_hand"] = new_snapshot["qty_on_hand"].astype("float64")
    new_snapshot["last_event_ts"] = pd.to_datetime(new_snapshot["last_event_ts"]).astype("datetime64[us]")

    return {"new_snapshot": new_snapshot}
